'use client';

import { FormEvent, PointerEvent, useEffect, useMemo, useRef, useState } from 'react';

type Role = 'employee' | 'leader' | 'hr';
type PageId = 'dashboard' | 'attendance' | 'tasks' | 'virtual-office' | 'leave' | 'team' | 'approvals' | 'employees' | 'profile' | 'settings';
type ModalId = 'announcement' | 'announcement-detail' | 'leave' | 'task' | 'people' | 'photo-checkin' | 'meeting-a' | 'meeting-b' | 'lounge' | 'work' | 'review-reason' | null;

const basePages = [
  ['dashboard', 'Dashboard', '⌂'], ['attendance', 'Attendance', '◷'], ['tasks', 'Tasks', '✓'],
  ['virtual-office', 'Virtual Office', '▦'], ['leave', 'Leave', '☂'], ['team', 'Team', '♟'],
] as const;
const roleName = (role: Role) => role === 'leader' ? 'Team Leader' : role === 'hr' ? 'HR' : 'Employee';
const demoAccounts = [
  ['Beau','demo@komorebi.local','employee'], ['Night','leader@komorebi.local','leader'], ['Aom','hr@komorebi.local','hr'],
  ['Mina','mina@komorebi.local','employee'], ['Rin','rin@komorebi.local','employee'], ['Ploy','ploy@komorebi.local','employee'],
  ['Jay','jay@komorebi.local','employee'], ['Nara','nara@komorebi.local','employee'],
] as const;
const demoPassword='Demo1234!';
type AnnouncementNote=[string,string,string,string,string];

async function apiRequest<T>(path:string, init:RequestInit={}) {
  const token=localStorage.getItem('komorebi-token');
  const headers=new Headers(init.headers);
  if(token)headers.set('Authorization',`Bearer ${token}`);
  if(init.body&&!(init.body instanceof FormData))headers.set('Content-Type','application/json');
  const response=await fetch(`/api${path}`,{...init,headers});
  if(!response.ok)throw new Error((await response.json().catch(()=>null))?.message??'Request failed');
  return response.status===204?null as T:response.json() as Promise<T>;
}

type RealtimeEvent={resource:string;title?:string;body?:string};
async function readRealtime(signal:AbortSignal,onEvent:(event:RealtimeEvent)=>void){
  const token=localStorage.getItem('komorebi-token');
  const response=await fetch('/api/events',{headers:{Authorization:`Bearer ${token}`},signal,cache:'no-store'});
  if(!response.ok||!response.body)throw new Error('Realtime connection unavailable');
  const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='';
  while(!signal.aborted){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const blocks=buffer.split(/\r?\n\r?\n/);buffer=blocks.pop()??'';for(const block of blocks){const data=block.split(/\r?\n/).filter(x=>x.startsWith('data:')).map(x=>x.slice(5).trim()).join('\n');if(data)try{const parsed=JSON.parse(data);if(parsed.resource)onEvent(parsed)}catch{}}}
}

export function KomorebiApp() {
  const [role, setRole] = useState<Role | null>(null);
  const [booting,setBooting]=useState(true);
  const [page, setPage] = useState<PageId>('dashboard');
  const [menu, setMenu] = useState(false);
  const [notices, setNotices] = useState(false);
  const [modal, setModal] = useState<ModalId>(null);
  const [checkedIn, setCheckedIn] = useState(false);
  const [mode, setMode] = useState<'office' | 'wfh'>('office');
  const [drag, setDrag] = useState(0);
  const [dragging,setDragging]=useState(false);
  const [selectedAnnouncement, setSelectedAnnouncement] = useState(0);
  const [announcementNotes,setAnnouncementNotes]=useState<AnnouncementNote[]>([]);
  const [refreshVersion,setRefreshVersion]=useState(0);
  const dragStart = useRef<number | null>(null);
  const dragValue = useRef(0);
  const didDrag = useRef(false);
  const browserNotices = useRef(false);
  const pages = useMemo(() => {
    const extras = role === 'leader' ? [['approvals','Approvals','◎']] : role === 'hr' ? [['approvals','Approvals','◎'],['employees','Employees','♟']] : [];
    return [...basePages, ...extras, ['profile','Profile','☺'], ['settings','Settings','⚙']] as [PageId,string,string][];
  }, [role]);
  const index = Math.max(0, pages.findIndex(([id]) => id === page));
  const previous = pages[(index - 1 + pages.length) % pages.length];
  const next = pages[(index + 1) % pages.length];
  const go = (id: PageId) => { setPage(id); setMenu(false); setNotices(false); window.scrollTo({top:0,behavior:'smooth'}); };
  const finishDrag = () => { const distance=dragValue.current;if (distance > 45) go(previous[0]); else if (distance < -45) go(next[0]);didDrag.current=Math.abs(distance)>5;dragStart.current=null;dragValue.current=0;setDrag(0);setDragging(false);window.setTimeout(()=>{didDrag.current=false},0); };
  useEffect(()=>{const token=localStorage.getItem('komorebi-token');if(!token){queueMicrotask(()=>setBooting(false));return}apiRequest<{role:'EMPLOYEE'|'TEAM_LEADER'|'HR'}>('/auth/me').then(user=>setRole(user.role==='TEAM_LEADER'?'leader':user.role==='HR'?'hr':'employee')).catch(()=>localStorage.removeItem('komorebi-token')).finally(()=>setBooting(false))},[]);
  useEffect(()=>{if(!role)return;apiRequest<Array<{status:string;workMode:'OFFICE'|'WFH'}>>('/attendance').then(rows=>{const active=rows.find(x=>x.status==='WORKING');setCheckedIn(Boolean(active));if(active)setMode(active.workMode==='OFFICE'?'office':'wfh')}).catch(()=>undefined)},[role]);
  useEffect(()=>{if(!role)return;const load=()=>apiRequest<Array<{title:string;body:string;createdAt:string;author:{displayName:string}}>>('/announcements').then(data=>setAnnouncementNotes(data.map((x,i)=>[x.title,x.body,['yellow','blue','green'][i%3],x.author.displayName,x.createdAt]))).catch(()=>setAnnouncementNotes([]));const realtime=(event:Event)=>{if((event as CustomEvent<RealtimeEvent>).detail?.resource==='announcements')void load()};void load();window.addEventListener('komorebi:announcements',load);window.addEventListener('komorebi:realtime',realtime);return()=>{window.removeEventListener('komorebi:announcements',load);window.removeEventListener('komorebi:realtime',realtime)}},[role]);
  useEffect(()=>{if(!role)return;let stopped=false;const controller=new AbortController();void apiRequest<{emailNotifications:boolean}>('/preferences').then(x=>{browserNotices.current=x.emailNotifications;localStorage.setItem('komorebi-browser-notifications',String(x.emailNotifications))}).catch(()=>undefined);const run=async()=>{while(!stopped){try{await readRealtime(controller.signal,event=>{setRefreshVersion(x=>x+1);window.dispatchEvent(new CustomEvent('komorebi:realtime',{detail:event}));if(event.title&&localStorage.getItem('komorebi-browser-notifications')==='true'&&'Notification'in window&&Notification.permission==='granted')new Notification(event.title,{body:event.body,tag:`komorebi-${event.resource}`})})}catch{}if(!stopped)await new Promise(resolve=>window.setTimeout(resolve,2500))}};void run();return()=>{stopped=true;controller.abort()}},[role]);
  const check=async()=>{if(checkedIn){await apiRequest('/attendance/check-out',{method:'POST'});setCheckedIn(false)}else if(mode==='office')setModal('photo-checkin');else{await apiRequest('/attendance/check-in',{method:'POST',body:JSON.stringify({workMode:'WFH'})});setCheckedIn(true)}};
  const officeCheckIn=async(photo:File)=>{const form=new FormData();form.set('workMode','OFFICE');form.set('photo',photo);await apiRequest('/attendance/check-in',{method:'POST',body:form});setCheckedIn(true);setModal(null)};

  if(booting)return <main className="login-view"><div className="ambient"/><div className="brand splash-brand"><span className="brand-mark">⌁</span>Komorebi Office</div></main>;
  if (!role) return <Login onRole={setRole} />;
  return <div className="app-view">
    <div className="ambient" aria-hidden="true" />
    <header className="nav-shell">
      <nav className="glass top-nav">
        <button className="icon-button menu-trigger" onClick={()=>setMenu(!menu)} aria-label="Open menu"><span/><span/><span/></button>
        <div className="carousel-window">
          <button className="icon-button nav-arrow" aria-label="Previous page" onPointerDown={e=>e.stopPropagation()} onClick={()=>go(previous[0])}>‹</button>
          <div className={`carousel-track ${dragging?'dragging':''}`} style={{transform:`translateX(${drag}px)`}} onPointerDown={(e:PointerEvent)=>{dragStart.current=e.clientX;dragValue.current=0;setDragging(true);e.currentTarget.setPointerCapture(e.pointerId)}} onPointerMove={(e:PointerEvent)=>{if(dragStart.current!==null){const value=e.clientX-dragStart.current;dragValue.current=value;setDrag(value)}}} onPointerUp={finishDrag} onPointerCancel={finishDrag}>
            <button className="nav-item nav-peek" onClick={()=>!didDrag.current&&go(previous[0])}>{previous[1]}</button>
            <button className="current-menu" onClick={()=>!didDrag.current&&setMenu(true)}>{pages[index][1]}</button>
            <button className="nav-item nav-peek" onClick={()=>!didDrag.current&&go(next[0])}>{next[1]}</button>
          </div>
          <button className="icon-button nav-arrow" aria-label="Next page" onPointerDown={e=>e.stopPropagation()} onClick={()=>go(next[0])}>›</button>
        </div>
        <button className="icon-button notification-trigger" onClick={()=>{setNotices(!notices);setMenu(false)}} aria-label="Notifications">♢<i/></button>
      </nav>
      {menu && <NavMenu role={role} pages={pages} current={page} go={go} signOut={()=>{localStorage.removeItem('komorebi-token');setMenu(false);setPage('dashboard');setRole(null)}} />}
      {notices && <Notifications />}
    </header>
    {menu && <button className="menu-scrim" onClick={()=>setMenu(false)} aria-label="Close menu" />}
    <main className="screen"><Screen key={`${page}-${refreshVersion}`} page={page} role={role} announcements={announcementNotes} checkedIn={checkedIn} mode={mode} setMode={setMode} check={()=>void check()} modal={setModal} openAnnouncement={(i)=>{setSelectedAnnouncement(i);setModal('announcement-detail')}}/></main>
    {modal && <Modal id={modal} role={role} announcement={announcementNotes[selectedAnnouncement]} close={()=>setModal(null)} checkIn={officeCheckIn} />}
  </div>;
}

function Login({onRole}:{onRole:(role:Role)=>void}) {
  const [error,setError]=useState(''); const [loading,setLoading]=useState(false);
  const enter=(nextRole:Role)=>{window.scrollTo(0,0);onRole(nextRole)};
  async function login(email:string,password:string){setLoading(true);setError('');try{const res=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});if(!res.ok)throw new Error();const data=await res.json();localStorage.setItem('komorebi-token',data.accessToken);enter(data.user.role==='TEAM_LEADER'?'leader':data.user.role==='HR'?'hr':'employee')}catch{setError('Unable to sign in. Please check your details.')}finally{setLoading(false)}}
  const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const data=new FormData(e.currentTarget);void login(String(data.get('email')),String(data.get('password')))};
  return <main className="login-view"><div className="ambient"/><div className="login-wrap"><div className="brand"><span className="brand-mark">⌁</span>Komorebi Office</div><section className="glass login-card"><div className="welcome-mark">⌁</div><h1>Welcome back</h1><p className="muted center">Sign in to start your workday.</p><form onSubmit={submit}><label className="field">Email<input name="email" type="email" placeholder="you@company.com" required/></label><label className="field">Password<input name="password" type="password" minLength={8} placeholder="Enter your password" required/></label><button className="button primary wide" disabled={loading}>{loading?'Signing in…':'Sign In'}</button><p className="form-message">{error}</p></form><div className="demo-divider"><span>Real demo accounts</span></div><div className="demo-account-list">{demoAccounts.map(([name,email,role])=><button key={email} className={`demo-account ${role}`} onClick={()=>void login(email,demoPassword)}><span className="avatar mini">{name[0]}</span><span><strong>{name}</strong><small>{roleName(role)} · {email}</small></span></button>)}</div><p className="tiny center">All accounts use the demo password shown in the project documentation.</p></section></div></main>;
}

function NavMenu({role,pages,current,go,signOut}:{role:Role;pages:[PageId,string,string][];current:PageId;go:(id:PageId)=>void;signOut:()=>void}){const [profile,setProfile]=useState<{displayName:string;jobTitle:string|null;team:{name:string}|null}|null>(null);useEffect(()=>{apiRequest<typeof profile>('/profile').then(setProfile).catch(()=>undefined)},[]);return <div className="glass overlay-panel menu-panel"><button className="menu-role" onClick={()=>go('profile')}><span className="avatar mini">{profile?.displayName?.[0]??(role==='leader'?'TL':role==='hr'?'HR':'E')}</span><div><strong>{profile?.displayName??roleName(role)}</strong><small>{profile?.jobTitle??profile?.team?.name??roleName(role)} · View profile</small></div></button><div className="menu-grid">{pages.filter(([id])=>id!=='profile').map(([id,label,icon])=><button key={id} className={`menu-item ${id===current?'active':''}`} onClick={()=>go(id)}><span>{icon}</span><span>{label}</span></button>)}<div className="menu-divider"/><button className="menu-item" onClick={signOut}><span>⇄</span><span>Switch account</span></button><button className="menu-item" onClick={signOut}><span>↪</span><span>Sign Out</span></button></div></div>}
function Notifications(){type Notice={id:string;title:string;createdAt:string;readAt:string|null};const [rows,setRows]=useState<Notice[]>([]);useEffect(()=>{const load=()=>apiRequest<Notice[]>('/notifications').then(setRows).catch(()=>setRows([]));const realtime=(event:Event)=>{if((event as CustomEvent<RealtimeEvent>).detail?.resource==='notifications')void load()};void load();window.addEventListener('komorebi:realtime',realtime);return()=>window.removeEventListener('komorebi:realtime',realtime)},[]);return <div className="glass overlay-panel notification-panel"><h3>Notifications</h3>{rows.map((item,i)=><button className={`notice-row notice-button ${item.readAt?'read':''}`} key={item.id} onClick={()=>{void apiRequest(`/notifications/${item.id}/read`,{method:'PATCH'});setRows(rows.map(x=>x.id===item.id?{...x,readAt:new Date().toISOString()}:x))}}><span className="notice-icon">{['☂','✓','✦'][i%3]}</span><div><p>{item.title}</p><span>{new Date(item.createdAt).toLocaleString()}</span></div></button>)}{!rows.length&&<p className="empty-people">No notifications yet.</p>}</div>}

function Screen({page,role,announcements,checkedIn,mode,setMode,check,modal,openAnnouncement}:{page:PageId;role:Role;announcements:AnnouncementNote[];checkedIn:boolean;mode:'office'|'wfh';setMode:(m:'office'|'wfh')=>void;check:()=>void;modal:(m:ModalId)=>void;openAnnouncement:(i:number)=>void}){
  if(page==='dashboard')return <Dashboard role={role} announcements={announcements} checkedIn={checkedIn} mode={mode} setMode={setMode} check={check} modal={modal} openAnnouncement={openAnnouncement}/>;
  if(page==='attendance')return <Attendance checkedIn={checkedIn} mode={mode} setMode={setMode} check={check}/>;
  if(page==='tasks')return <Tasks role={role} modal={modal}/>;
  if(page==='virtual-office')return <VirtualOffice modal={modal}/>;
  if(page==='leave')return <Leave modal={modal}/>;
  if(page==='team')return <Team/>;
  if(page==='approvals')return <Approvals role={role}/>;
  if(page==='employees')return <Employees/>;
  if(page==='profile')return <Profile role={role}/>;
  return <Settings/>;
}

function Dashboard({role,announcements,checkedIn,mode,setMode,check,modal,openAnnouncement}:{role:Role;announcements:AnnouncementNote[];checkedIn:boolean;mode:'office'|'wfh';setMode:(m:'office'|'wfh')=>void;check:()=>void;modal:(m:ModalId)=>void;openAnnouncement:(i:number)=>void}){const [summary,setSummary]=useState<{dueTasks:number;highPriority:number;teamWfh:{id:string;displayName:string}[]}|null>(null);useEffect(()=>{apiRequest<typeof summary>('/dashboard').then(setSummary).catch(()=>setSummary(null))},[]);const today=[summary&&{title:`${summary.dueTasks} task${summary.dueTasks===1?'':'s'} due today`,detail:`${summary.highPriority} open high-priority task${summary.highPriority===1?'':'s'}`},...(summary?.teamWfh??[]).map(person=>({title:`${person.displayName} is working from home`,detail:'Komorebi Product'}))].filter(Boolean) as {title:string;detail:string}[];return <><section className="notice-board"><div className="board-head"><div><p className="eyebrow">Office board</p><h2>Announcements</h2></div>{role!=='employee'&&<button className="button blue" onClick={()=>modal('announcement')}>+ New announcement</button>}</div><div className="post-grid">{announcements.map(([title,body,color,,createdAt],i)=><button key={`${title}-${i}`} className={`post-it ${color}`} onClick={()=>openAnnouncement(i)}><span className="pin">⌖</span><span className="post-date">{new Date(createdAt).toLocaleDateString()}</span><strong>{title}</strong><span>{body}</span><em>Open note</em></button>)}{!announcements.length&&<div className="empty-people">No announcements have been posted.</div>}</div></section><div className="grid two dashboard-main"><section className="card hero-card"><div className="status-orb">◷</div><p className="eyebrow">Today&apos;s Attendance</p><h2>{checkedIn?`Working · ${mode==='office'?'Office':'WFH'}`:'Not checked in'}</h2>{!checkedIn&&<Mode value={mode} set={setMode}/>}<button className="button primary" onClick={check}>{checkedIn?'Check Out':'Check In'}</button></section><section className="card"><div className="card-title"><h3>Today</h3></div><div className="list">{today.map(item=><div className="list-row" key={`${item.title}-${item.detail}`}><div><p>{item.title}</p><small>{item.detail}</small></div><span>✦</span></div>)}{summary&&today.length===0&&<p className="empty-people">Nothing scheduled from your workspace data today.</p>}</div></section></div></>}
function Mode({value,set}:{value:'office'|'wfh';set:(m:'office'|'wfh')=>void}){return <div className="mode-row"><button className={`chip ${value==='office'?'active':''}`} onClick={()=>set('office')}>Office</button><button className={`chip ${value==='wfh'?'active':''}`} onClick={()=>set('wfh')}>WFH</button></div>}
function Attendance({checkedIn,mode,setMode,check}:{checkedIn:boolean;mode:'office'|'wfh';setMode:(m:'office'|'wfh')=>void;check:()=>void}){
  type CalendarData={month:string;attendance:{checkedIn:string;workMode:'OFFICE'|'WFH'}[];leaves:{startDate:string;endDate:string}[]};
  const today=new Date();const [cursor,setCursor]=useState(new Date(today.getFullYear(),today.getMonth(),1));const [data,setData]=useState<CalendarData|null>(null);
  const monthKey=`${cursor.getFullYear()}-${String(cursor.getMonth()+1).padStart(2,'0')}`;
  useEffect(()=>{apiRequest<CalendarData>(`/attendance/calendar?month=${monthKey}`).then(setData).catch(()=>setData(null))},[checkedIn,monthKey]);
  const count=new Date(cursor.getFullYear(),cursor.getMonth()+1,0).getDate();const offset=(new Date(cursor.getFullYear(),cursor.getMonth(),1).getDay()+6)%7;
  const days=Array.from({length:count},(_,i)=>{const date=new Date(cursor.getFullYear(),cursor.getMonth(),i+1);const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const attendance=data?.attendance.find(x=>x.checkedIn.slice(0,10)===key);const leave=data?.leaves.some(x=>key>=x.startDate.slice(0,10)&&key<=x.endDate.slice(0,10));const label=attendance?(attendance.workMode==='OFFICE'?'Office':'WFH'):leave?'Leave':date.getDay()===0||date.getDay()===6?'Holiday':'';return{day:i+1,label,isToday:key===`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`}});
  const counts=['Office','WFH','Leave'].map(label=>({label,count:days.filter(day=>day.label===label).length}));
  return <><section className="card hero-card compact-hero"><p className="eyebrow">Current status</p><div className="status-orb">▣</div><h2>{checkedIn?`Working from ${mode==='office'?'Office':'home'}`:'Ready to begin'}</h2>{!checkedIn&&<Mode value={mode} set={setMode}/>}<button className="button primary" onClick={check}>{checkedIn?'Check Out':'Check In'}</button></section><section className="card calendar-card"><div className="attendance-month"><button className="icon-button" aria-label="Previous month" onClick={()=>setCursor(new Date(cursor.getFullYear(),cursor.getMonth()-1,1))}>‹</button><div><p className="eyebrow">Attendance calendar</p><h3>{cursor.toLocaleString(undefined,{month:'long',year:'numeric'})}</h3></div><button className="icon-button" aria-label="Next month" onClick={()=>setCursor(new Date(cursor.getFullYear(),cursor.getMonth()+1,1))}>›</button></div><div className="calendar-summary">{counts.map(item=><div key={item.label} className={item.label.toLowerCase()}><span>{item.label}</span><strong>{item.count}</strong></div>)}</div><div className="calendar-legend">{['Office','WFH','Leave','Holiday'].map(x=><span key={x} className={`cal-tag ${x.toLowerCase()}`}>{x}</span>)}</div><div className="calendar">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=><span className="cal-head" key={x}>{x}</span>)}{Array.from({length:offset},(_,i)=><span className="cal-empty" key={`blank-${i}`}/>) }{days.map(x=><div className={`cal-day ${x.label.toLowerCase()} ${x.isToday?'is-today':''}`} key={x.day}><strong>{x.day}</strong>{x.label&&<span>{x.label}</span>}</div>)}</div></section></>}
function Tasks({role,modal}:{role:Role;modal:(m:ModalId)=>void}){
  type UiTask={id:string;title:string;description:string;priority:string;status:string;dueAt:string|null;assignees:{user:{id:string;displayName:string}}[]};
  const [tasks,setTasks]=useState<UiTask[]>([]);
  const [userId,setUserId]=useState('');
  const [filter,setFilter]=useState('All');
  const [selected,setSelected]=useState<UiTask|null>(null);
  const [submission,setSubmission]=useState('');
  const [taskNow]=useState(()=>Date.now());
  const load=()=>apiRequest<UiTask[]>('/tasks').then(setTasks).catch(()=>setTasks([]));
  useEffect(()=>{void load();apiRequest<{id:string}>('/auth/me').then(x=>setUserId(x.id)).catch(()=>setUserId(''))},[]);
  const dueSoon=(task:UiTask)=>Boolean(task.dueAt)&&new Date(task.dueAt!).getTime()<=taskNow+7*86_400_000;
  const visible=tasks.filter(x=>filter==='All'||filter==='Mine'&&x.assignees.some(a=>a.user.id===userId)||filter==='High Priority'&&x.priority==='HIGH'||filter==='Due Soon'&&x.status!=='DONE'&&dueSoon(x));
  const columns=[['TODO','TO DO'],['IN_PROGRESS','IN PROGRESS'],['DONE','DONE']].map(([status,label])=>[label,visible.filter(x=>x.status===status||(status==='IN_PROGRESS'&&x.status==='SUBMITTED'))] as const);
  const canSubmit=(task:UiTask)=>task.assignees.some(a=>a.user.id===userId)&&task.status!=='DONE'&&task.status!=='SUBMITTED';
  const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!selected||!submission.trim())return;await apiRequest(`/tasks/${selected.id}/submit`,{method:'POST',body:JSON.stringify({note:submission.trim()})});setSelected(null);setSubmission('');await load()};
  return <><div className="task-toolbar"><div className="filters task-filters">{['All','Mine','High Priority','Due Soon'].map(x=><button onClick={()=>setFilter(x)} className={`chip ${filter===x?'active':''}`} key={x}>{x}</button>)}</div>{role!=='employee'&&<button className="button blue" onClick={()=>modal('task')}>+ Assign task</button>}</div><div className="board task-board">{columns.map(([name,items])=><section className={`column ${items.length?'':'empty-filter'}`} key={name}><div className="column-head"><span>{name}</span><span>{items.length}</span></div>{items.map(item=><button className="task-card" key={item.id} onClick={()=>setSelected(item)}><span className={`badge ${item.priority==='HIGH'?'red':'yellow'}`}>{item.priority[0]+item.priority.slice(1).toLowerCase()}</span><p>{item.title}</p><div className="task-meta"><span>{item.dueAt?new Date(item.dueAt).toLocaleDateString():'No due date'}</span><span>•••</span></div></button>)}</section>)}</div>{selected&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setSelected(null)}><section className="glass modal-card"><button className="icon-button modal-close" onClick={()=>setSelected(null)}>×</button><p className="eyebrow">Task details</p><h2>{selected.title}</h2><p>{selected.description}</p><p className="muted">Assigned to {selected.assignees.map(x=>x.user.displayName).join(', ')}</p>{canSubmit(selected)?<form className="modal-section" onSubmit={submit}><label className="field">Submission note<textarea required value={submission} onChange={e=>setSubmission(e.target.value)} placeholder="Describe the completed work"/></label><button className="button primary wide" disabled={!submission.trim()}>Submit for approval</button></form>:<p className="approval-note">Status: {selected.status.replaceAll('_',' ')}</p>}</section></div>}</>;
}
function VirtualOffice({modal}:{modal:(m:ModalId)=>void}){
  type Presence={userId:string;room:'WORK_AREA'|'MEETING_A'|'MEETING_B'|'LOUNGE';x:number;y:number;user:{id:string;displayName:string}};
  type Room='work'|'meeting-a'|'meeting-b'|'lounge';const rooms:Record<Room,Presence['room']>={work:'WORK_AREA','meeting-a':'MEETING_A','meeting-b':'MEETING_B',lounge:'LOUNGE'};
  const roomNames:Record<Presence['room'],Room>={WORK_AREA:'work',MEETING_A:'meeting-a',MEETING_B:'meeting-b',LOUNGE:'lounge'};
  const [room,setRoom]=useState<Room>('work');const [people,setPeople]=useState<Presence[]>([]);const [me,setMe]=useState<{id:string;displayName:string}|null>(null);
  const load=()=>apiRequest<Presence[]>('/office/presence').then(setPeople).catch(()=>setPeople([]));
  useEffect(()=>{void Promise.all([apiRequest<{id:string;displayName:string}>('/auth/me'),apiRequest<Presence[]>('/office/presence')]).then(async([user,rows])=>{setMe(user);setPeople(rows);const mine=rows.find(x=>x.userId===user.id);if(mine)setRoom(roomNames[mine.room]);else{await apiRequest('/office/presence',{method:'PATCH',body:JSON.stringify({room:'WORK_AREA',x:50,y:58})});await load()}})},[]);
  const dbRoom=rooms[room];const here=people.filter(x=>x.room===dbRoom);const mine=here.find(x=>x.userId===me?.id);
  const savePosition=async(x:number,y:number)=>{if(!me)return;setPeople(current=>{const existing=current.find(item=>item.userId===me.id);const next:Presence={userId:me.id,room:dbRoom,x,y,user:me};return existing?current.map(item=>item.userId===me.id?next:item):[...current,next]});await apiRequest('/office/presence',{method:'PATCH',body:JSON.stringify({room:dbRoom,x,y})})};
  const walk=(event:PointerEvent<HTMLElement>)=>{if((event.target as HTMLElement).closest('button'))return;const rect=event.currentTarget.getBoundingClientRect();const x=Math.max(5,Math.min(95,((event.clientX-rect.left)/rect.width)*100));const y=Math.max(12,Math.min(90,((event.clientY-rect.top)/rect.height)*100));void savePosition(x,y)};
  const move=async(next:Room,openMeeting=false)=>{setRoom(next);const nextDb=rooms[next];setPeople(current=>current.filter(x=>x.userId!==me?.id));await apiRequest('/office/presence',{method:'PATCH',body:JSON.stringify({room:nextDb,x:50,y:58})});await load();if(openMeeting&&next.startsWith('meeting'))modal(next)};
  const avatars=here.filter(x=>x.userId!==me?.id);
  return <><div className="warp-row"><button className="warp-button" onClick={()=>void move('meeting-a',true)}>⚡ Meeting A</button><button className="warp-button" onClick={()=>void move('meeting-b',true)}>⚡ Meeting B</button><button className="warp-button" onClick={()=>void move('lounge')}>⚡ Lounge</button><button className="warp-button" onClick={()=>modal('people')}>♟ Employees</button></div><section className={`office-game scene-${room}`} onPointerUp={walk}>{mine&&<i className="player walking-player" style={{left:`${mine.x}%`,top:`${mine.y}%`}}><b>{me?.displayName[0]}</b><span>{me?.displayName}</span></i>}{avatars.map(person=><i className="game-person live-person" key={person.userId} style={{left:`${person.x}%`,top:`${person.y}%`}}>{person.user.displayName[0]}<span>{person.user.displayName}</span></i>)}{room==='work'?<><div className="scene-label"><strong>Work area</strong><span>{here.length} people here</span></div><div className="room work-zone"><span className="office-rug"/><span className="plant plant-one">♧</span><span className="plant plant-two">♧</span>{[0,1,2,3,4,5].map(i=><span className="game-desk decorative" key={i} style={{left:`${9+(i%3)*27}%`,top:`${22+Math.floor(i/3)*36}%`}}/>)}</div><button className="game-door door-a" onClick={()=>void move('meeting-a')}><span className="door-panel">A</span><strong>Meeting A</strong></button><button className="game-door door-b" onClick={()=>void move('meeting-b')}><span className="door-panel">B</span><strong>Meeting B</strong></button><button className="game-door door-lounge" onClick={()=>void move('lounge')}><span className="door-panel">☕</span><strong>Lounge</strong></button></>:<><button className="room-back" onClick={()=>void move('work')}>← Work area</button><div className="scene-label"><strong>{room==='meeting-a'?'Meeting Room A':room==='meeting-b'?'Meeting Room B':'Lounge'}</strong><span>{here.length?`${here.length} people here`:'The room is empty'}</span></div>{room.startsWith('meeting')?<button className="meeting-table" onClick={()=>modal(room)}><span>▣</span><strong>Conference table</strong><small>Open meeting link</small></button>:<><div className="lounge-sofa"/><div className="coffee-table">☕</div></>}</>}</section></>}
function Leave({modal}:{modal:(m:ModalId)=>void}){type LeaveRow=[string,string,string,string,string?];type Balance={type:string;remaining:number};const [reason,setReason]=useState<string|null>(null);const [rows,setRows]=useState<LeaveRow[]>([]);const [balances,setBalances]=useState<Balance[]>([]);useEffect(()=>{void Promise.all([apiRequest<Array<{id:string;type:string;startDate:string;endDate:string;status:string;approvals:Array<{note:string|null}>}>>('/leaves').then(data=>setRows(data.map(x=>[`${x.type[0]+x.type.slice(1).toLowerCase()} Leave`,`${new Date(x.startDate).toLocaleDateString()} – ${new Date(x.endDate).toLocaleDateString()}`,x.status==='PENDING_LEADER'?'Pending 0/2':x.status==='PENDING_HR'?'Pending 1/2':x.status==='APPROVED'?'Approved':'Not approved',x.status==='APPROVED'?'green':x.status==='REJECTED'?'red':'yellow',x.approvals.find(a=>a.note)?.note??undefined]))),apiRequest<Balance[]>('/leaves/balances').then(setBalances)]).catch(()=>{setRows([]);setBalances([])})},[]);return <><button className="button primary" onClick={()=>modal('leave')}>+ Request Leave</button><div className="grid three balance-scroll">{balances.map(item=><section className="card balance-card" key={item.type}><span className="muted">{item.type[0]+item.type.slice(1).toLowerCase()}</span><strong>{item.remaining} days</strong><small className="muted">remaining</small></section>)}</div><section className="card leave-history"><div className="card-title"><h3>Leave history</h3></div><div className="list">{rows.map((x,i)=><div className="list-row leave-row" key={`${x[1]}-${i}`}><div><p>{x[0]}</p><small>{x[1]}</small></div><div className="leave-status"><span className={`badge ${x[3]}`}>{x[2]}</span>{x[2]==='Not approved'&&<button className="reason-button" onClick={()=>setReason(reason===x[1]?null:x[1])}>Reason</button>}</div>{x[2]==='Not approved'&&reason===x[1]&&<p className="rejection-reason">{x[4]??'No additional reason was provided.'}</p>}</div>)}{!rows.length&&<p className="empty-people">No leave requests yet.</p>}</div></section></>}
function Team(){type TeamRow={id:string;displayName:string;jobTitle:string|null;role:string;department:{name:string};presence:{room:string}|null;attendances:{workMode:string;status:string;checkedIn:string}[]};const [rows,setRows]=useState<TeamRow[]>([]);useEffect(()=>{apiRequest<TeamRow[]>('/team').then(setRows).catch(()=>setRows([]))},[]);return <section className="card"><div className="team-list"><div className="team-row team-head"><span>Teammate</span><span>Role</span><span>Work mode</span><span>Status</span></div>{rows.map(x=>{const attendance=x.attendances[0];const mode=attendance?.status==='WORKING'?(attendance.workMode==='WFH'?'WFH':'Office'):'—';const status=x.presence?.room==='MEETING_A'||x.presence?.room==='MEETING_B'?'In meeting':x.presence?.room&&x.presence.room!=='OFFLINE'?'Available':'Offline';return <button className="team-row" key={x.id}><span className="profile-row"><i className="avatar">{x.displayName[0]}</i><span><strong>{x.displayName}</strong><small>{x.jobTitle??x.department.name}</small></span></span><span>{x.role==='TEAM_LEADER'?'Team Leader':x.role==='HR'?'HR':'Employee'}</span><span>{mode}</span><span className={`badge ${status==='Offline'?'':'green'}`}>{status}</span></button>})}{!rows.length&&<div className="empty-people">No team members found.</div>}</div></section>}
function Approvals({role}:{role:Role}){type ReviewItem={id:string;name:string;summary:string};const [tab,setTab]=useState<'leave'|'task'>('leave');const [items,setItems]=useState<ReviewItem[]>([]);const [reasonFor,setReasonFor]=useState<ReviewItem|null>(null);const [note,setNote]=useState('');const load=()=>apiRequest<Array<Record<string,unknown>>>(`/approvals/${tab==='leave'?'leaves':'tasks'}`).then(data=>setItems(data.map(item=>tab==='leave'?{id:String(item.id),name:String((item.user as {displayName?:string})?.displayName??'Employee'),summary:`${new Date(String(item.startDate)).toLocaleDateString()} – ${new Date(String(item.endDate)).toLocaleDateString()} · ${String(item.reason)}`}:{id:String(item.id),name:String((item.submitter as {displayName?:string})?.displayName??'Employee'),summary:String(item.note??'Task submitted for review.')}))).catch(()=>setItems([]));useEffect(()=>{void load()},[tab]);const review=async(item:ReviewItem,decision:'APPROVED'|'REJECTED'|'CHANGES_REQUESTED',explanation?:string)=>{await apiRequest(`/approvals/${tab==='leave'?'leaves':'tasks'}/${item.id}`,{method:'PATCH',body:JSON.stringify({decision,note:explanation})});setItems(items.filter(x=>x.id!==item.id));setReasonFor(null);setNote('')};return <><div className="segments approval-tabs"><button className={`segment ${tab==='leave'?'active':''}`} onClick={()=>setTab('leave')}>Leave Approvals</button><button className={`segment ${tab==='task'?'active':''}`} onClick={()=>setTab('task')}>Task Approvals</button></div>{tab==='leave'&&role==='leader'&&<div className="approval-note">Team Leader approval is step 1 of 2. HR must also approve before it becomes final.</div>}<div className="grid approval-grid">{items.map(item=><section className="card approval-card" key={item.id}><div className="review-person"><span className="avatar">{item.name[0]}</span><div><h2>{item.name}</h2><p className="muted">{tab==='leave'?'Leave request':'Submitted task'}</p></div></div><p>{item.summary}</p><div className="actions"><button className="button secondary" onClick={()=>setReasonFor(item)}>{tab==='leave'?'Reject':'Request changes'}</button><button className="button primary" onClick={()=>void review(item,'APPROVED')}>Approve</button></div></section>)}{!items.length&&<section className="card empty-people">Nothing is waiting for review.</section>}</div>{reasonFor&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setReasonFor(null)}><section className="glass modal-card"><button className="icon-button modal-close" onClick={()=>setReasonFor(null)}>×</button><p className="eyebrow">Review response</p><h2>{tab==='leave'?'Why is this request rejected?':'What needs to change?'}</h2><label className="field">Explanation<textarea autoFocus value={note} onChange={e=>setNote(e.target.value)} placeholder="Write a clear explanation"/></label><div className="actions end"><button className="button secondary" onClick={()=>setReasonFor(null)}>Cancel</button><button className="button primary" disabled={!note.trim()} onClick={()=>void review(reasonFor,tab==='leave'?'REJECTED':'CHANGES_REQUESTED',note)}>Send response</button></div></section></div>}</>}
type EmployeeDirectoryItem={id:string;displayName:string;email:string;jobTitle:string|null;role:string;department:{id:string;name:string};team:{id:string;name:string}|null;presence:{room:string}|null};
type EmployeeRow=[string,string,string,string,string,string];

function Employees(){
  const [query,setQuery]=useState('');
  const [department,setDepartment]=useState('All');
  const [role,setRole]=useState('All');
  const [showAdd,setShowAdd]=useState(false);
  const [saving,setSaving]=useState(false);
  const [error,setError]=useState('');
  const [directory,setDirectory]=useState<EmployeeDirectoryItem[]>([]);
  const [rows,setRows]=useState<EmployeeRow[]>([]);
  const load=async()=>{
    const data=await apiRequest<EmployeeDirectoryItem[]>('/employees');
    setDirectory(data);
    setRows(data.map(x=>[x.displayName,x.email,x.department.name,x.role==='TEAM_LEADER'?'Team Leader':x.role==='HR'?'HR':'Employee',x.jobTitle??'',x.presence?.room==='OFFLINE'||!x.presence?'Offline':'Available']));
  };
  useEffect(()=>{queueMicrotask(()=>void load().catch(()=>undefined))},[]);
  const submit=async(e:FormEvent<HTMLFormElement>)=>{
    e.preventDefault();setSaving(true);setError('');
    const data=new FormData(e.currentTarget);
    try{
      await apiRequest('/employees',{method:'POST',body:JSON.stringify({displayName:data.get('displayName'),jobTitle:data.get('jobTitle')||undefined,email:data.get('email'),password:data.get('password'),role:data.get('role'),departmentId:data.get('departmentId'),teamId:data.get('teamId')||undefined})});
      await load();setShowAdd(false);
    }catch(ex){setError(ex instanceof Error?ex.message:'Unable to add employee')}finally{setSaving(false)}
  };
  const filtered=rows.filter(x=>(!query||x[0].toLowerCase().includes(query.toLowerCase()))&&(department==='All'||x[2]===department)&&(role==='All'||x[3]===role));
  const departments=['All',...new Set(rows.map(x=>x[2]))];
  const departmentOptions=[...new Map(directory.map(x=>[x.department.id,x.department])).values()];
  const teamOptions=[...new Map(directory.filter(x=>x.team).map(x=>[x.team!.id,x.team!])).values()];
  return <>
    <section className="card employees-panel">
      <div className="employee-toolbar">
        <label className="search-field">⌕<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search employees"/></label>
        <div className="employee-actions"><div className="employee-filters"><label>Department<select value={department} onChange={e=>setDepartment(e.target.value)}>{departments.map(x=><option key={x}>{x}</option>)}</select></label><label>Role<select value={role} onChange={e=>setRole(e.target.value)}><option>All</option><option>Employee</option><option>Team Leader</option><option>HR</option></select></label></div><button className="button primary" onClick={()=>setShowAdd(true)}>+ Add employee</button></div>
      </div>
      <div className="team-list"><div className="team-row team-head"><span>Employee</span><span>Role</span><span>Department</span><span>Status</span></div>{filtered.map(x=><button className="team-row" key={x[1]||x[0]}><span className="profile-row"><i className="avatar">{x[0][0]}</i><span><strong>{x[0]}</strong>{x[1]&&<small>{x[1]}</small>}</span></span><span>{x[3]}</span><span>{x[2]}</span><span className="badge green">{x[5]}</span></button>)}{!filtered.length&&<div className="empty-people">No employees match these filters.</div>}</div>
    </section>
    {showAdd&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setShowAdd(false)}><section className="glass modal-card"><button className="icon-button modal-close" onClick={()=>setShowAdd(false)}>×</button><p className="eyebrow">HR · EMPLOYEES</p><h2>Add employee</h2><form className="modal-section" onSubmit={submit}><label className="field">Full name<input name="displayName" required placeholder="Employee name"/></label><label className="field">Job title<input name="jobTitle" placeholder="Product Engineer"/></label><label className="field">Work email<input name="email" type="email" required placeholder="name@company.com"/></label><label className="field">Temporary password<input name="password" type="password" minLength={8} required placeholder="At least 8 characters"/></label><div className="form-grid"><label className="field">Role<select name="role"><option value="EMPLOYEE">Employee</option><option value="TEAM_LEADER">Team Leader</option><option value="HR">HR</option></select></label><label className="field">Department<select name="departmentId" required defaultValue=""><option value="" disabled>Select department</option>{departmentOptions.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label></div><label className="field">Team<select name="teamId" defaultValue=""><option value="">No team</option>{teamOptions.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label>{error&&<p className="form-message">{error}</p>}<div className="actions end"><button type="button" className="button secondary" onClick={()=>setShowAdd(false)}>Cancel</button><button className="button primary" disabled={saving||!departmentOptions.length}>{saving?'Adding…':'Add employee'}</button></div></form></section></div>}
  </>
}
function Profile({role}:{role:Role}){
  type ProfileData={email:string;displayName:string;jobTitle:string|null;role:string;department:{name:string};team:{name:string}|null;avatarUpdatedAt:string|null};
  const [profile,setProfile]=useState<ProfileData|null>(null);const [name,setName]=useState('');const [avatar,setAvatar]=useState<File|null>(null);const [avatarUrl,setAvatarUrl]=useState('');const [editing,setEditing]=useState(false);const [saving,setSaving]=useState(false);const [message,setMessage]=useState('');
  const loadAvatar=async(updated:string|null)=>{if(!updated){setAvatarUrl('');return}const token=localStorage.getItem('komorebi-token');const response=await fetch('/api/profile/avatar',{headers:{Authorization:`Bearer ${token}`},cache:'no-store'});if(!response.ok)return;const url=URL.createObjectURL(await response.blob());setAvatarUrl(current=>{if(current)URL.revokeObjectURL(current);return url})};
  useEffect(()=>{apiRequest<ProfileData>('/profile').then(data=>{setProfile(data);setName(data.displayName);void loadAvatar(data.avatarUpdatedAt)}).catch(()=>setProfile(null));return()=>{if(avatarUrl)URL.revokeObjectURL(avatarUrl)}},[]);
  const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!name.trim())return;setSaving(true);setMessage('');const form=new FormData();form.set('displayName',name.trim());if(avatar)form.set('avatar',avatar);try{const updated=await apiRequest<ProfileData>('/profile',{method:'PATCH',body:form});setProfile(updated);setName(updated.displayName);setAvatar(null);setEditing(false);setMessage('Profile saved to the database.');await loadAvatar(updated.avatarUpdatedAt)}catch(ex){setMessage(ex instanceof Error?ex.message:'Unable to save profile')}finally{setSaving(false)}};
  if(!profile)return <section className="card detail-card"><p className="empty-people">Profile data is unavailable.</p></section>;
  return <section className="card detail-card profile-card"><div className="profile-hero"><div className="avatar large profile-photo">{avatarUrl?<img src={avatarUrl} alt="Profile"/>:profile.displayName[0]}</div><h2>{profile.displayName}</h2><p className="muted">{profile.jobTitle??roleName(role)} · {profile.department.name}</p><p>{profile.email}</p><button className="button secondary" onClick={()=>{setEditing(!editing);setMessage('')}}>{editing?'Cancel':'Edit profile'}</button></div>{editing&&<form className="profile-edit" onSubmit={save}><label className="field">Display name<input value={name} maxLength={80} required onChange={e=>setName(e.target.value)}/></label><label className="photo-drop compact"><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>setAvatar(e.target.files?.[0]??null)}/><strong>{avatar?.name??'Choose profile photo'}</strong><small>JPG, PNG or WebP · up to 2 MB</small></label><button className="button primary" disabled={saving}>{saving?'Saving…':'Save changes'}</button></form>}{message&&<p className="form-message profile-message">{message}</p>}<div className="detail-section"><h3>Personal Information</h3><div className="list"><div className="list-row"><span>Department</span><strong>{profile.department.name}</strong></div><div className="list-row"><span>Team</span><strong>{profile.team?.name??'No team'}</strong></div><div className="list-row"><span>Role</span><strong>{profile.role==='TEAM_LEADER'?'Team Leader':profile.role==='HR'?'HR':'Employee'}</strong></div></div></div></section>
}
function Settings(){
  type Preferences={emailNotifications:boolean;language:string;theme:string};const [prefs,setPrefs]=useState<Preferences|null>(null);const [permission,setPermission]=useState<'default'|'granted'|'denied'|'unsupported'>(()=>typeof window==='undefined'||!('Notification'in window)?'unsupported':Notification.permission);const secure=typeof window!=='undefined'&&window.isSecureContext;
  useEffect(()=>{apiRequest<Preferences>('/preferences').then(data=>{setPrefs(data);localStorage.setItem('komorebi-browser-notifications',String(data.emailNotifications))}).catch(()=>setPrefs(null))},[]);
  const update=async(next:Preferences)=>{const previous=prefs;setPrefs(next);localStorage.setItem('komorebi-browser-notifications',String(next.emailNotifications));try{await apiRequest('/preferences',{method:'PATCH',body:JSON.stringify(next)})}catch{setPrefs(previous);if(previous)localStorage.setItem('komorebi-browser-notifications',String(previous.emailNotifications))}};
  const toggleNotifications=async()=>{if(!prefs)return;if(prefs.emailNotifications){await update({...prefs,emailNotifications:false});return}if(!secure||!('Notification'in window)){setPermission('unsupported');return}const result=await Notification.requestPermission();setPermission(result);if(result==='granted'){await update({...prefs,emailNotifications:true});new Notification('Komorebi notifications are on',{body:'You will receive realtime updates while Komorebi is open.'})}};
  if(!prefs)return <section className="card detail-card"><p className="empty-people">Preferences are unavailable.</p></section>;
  const enabled=prefs.emailNotifications&&permission==='granted';
  return <section className="card detail-card"><div><h2>Workspace preferences</h2><p className="muted">Saved to your account.</p></div><div className="list"><div className="list-row notification-setting"><span><strong>Browser notifications</strong><small>{!secure?'Requires a secure HTTPS address':permission==='denied'?'Blocked in browser settings':enabled?'Permission granted and realtime alerts are active':'Ask this browser for permission'}</small></span><button className={`chip ${enabled?'active':''}`} onClick={()=>void toggleNotifications()}>{enabled?'On':prefs.emailNotifications?'Enable':'Off'}</button></div><div className="list-row"><span>Language</span><select value={prefs.language} onChange={e=>void update({...prefs,language:e.target.value})}><option>English</option><option>ไทย</option></select></div><div className="list-row"><span>Theme</span><strong>Komorebi light</strong></div></div></section>
}

function PeoplePanel(){type Contact={id:string;displayName:string;jobTitle:string|null;presence:{room:string}|null};type Message={id:string;senderId:string;recipientId:string;body:string;createdAt:string};const [contacts,setContacts]=useState<Contact[]>([]);const [contact,setContact]=useState<Contact|null>(null);const [chatOpen,setChatOpen]=useState(false);const [draft,setDraft]=useState('');const [messages,setMessages]=useState<Message[]>([]);useEffect(()=>{apiRequest<Contact[]>('/messages/contacts').then(setContacts).catch(()=>setContacts([]))},[]);useEffect(()=>{const refresh=(event:Event)=>{const detail=(event as CustomEvent<RealtimeEvent>).detail;if(detail?.resource==='messages'&&chatOpen&&contact)void apiRequest<Message[]>(`/messages/${contact.id}`).then(setMessages)};window.addEventListener('komorebi:realtime',refresh);return()=>window.removeEventListener('komorebi:realtime',refresh)},[chatOpen,contact]);const openChat=async()=>{if(!contact)return;setMessages(await apiRequest<Message[]>(`/messages/${contact.id}`));setChatOpen(true)};const send=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!draft.trim()||!contact)return;const sent=await apiRequest<Message>('/messages',{method:'POST',body:JSON.stringify({recipientId:contact.id,body:draft.trim()})});setMessages(current=>current.some(x=>x.id===sent.id)?current:[...current,sent]);setDraft('')};if(!contact)return <div className="office-people">{contacts.map(x=><button key={x.id} onClick={()=>setContact(x)}><span className="avatar">{x.displayName[0]}</span><span><strong>{x.displayName}</strong><small>{x.presence?.room&&x.presence.room!=='OFFLINE'?x.presence.room.replaceAll('_',' '):'Offline'}</small></span><span>›</span></button>)}{!contacts.length&&<p className="empty-people">No teammates are available.</p>}</div>;if(chatOpen)return <><div className="chat-head"><button className="icon-button" onClick={()=>setChatOpen(false)}>←</button><span className="avatar">{contact.displayName[0]}</span><span><strong>{contact.displayName}</strong><small>{contact.jobTitle??'Teammate'}</small></span></div><div className="chat-thread">{messages.map(message=><div className={`bubble ${message.senderId===contact.id?'':'mine'}`} key={message.id}>{message.body}</div>)}{!messages.length&&<p className="empty-people">No messages yet. Say hello.</p>}</div><form className="chat-compose" onSubmit={send}><input aria-label="Message" value={draft} onChange={e=>setDraft(e.target.value)} placeholder={`Message ${contact.displayName}`}/><button className="button primary" disabled={!draft.trim()}>↑</button></form></>;return <div className="person-card"><button className="person-back" onClick={()=>setContact(null)}>← Employees</button><span className="avatar large">{contact.displayName[0]}</span><h3>{contact.displayName}</h3><p className="muted">{contact.jobTitle??(contact.presence?.room??'Offline').replaceAll('_',' ')}</p><div className="contact-choice"><button className="button primary" onClick={()=>void openChat()}>Open chat</button><button className="button secondary" onClick={()=>window.open('https://meet.jit.si/KomorebiQuickCall','_blank','noopener,noreferrer')}>Call externally ↗</button></div></div>}

function MeetingPanel({room,close}:{room:'MEETING_A'|'MEETING_B';close:()=>void}){
  type Space={room:string;name:string;externalUrl:string};
  type Presence={room:string;user:{displayName:string}};
  const [space,setSpace]=useState<Space|null>(null);
  const [people,setPeople]=useState<string[]>([]);
  useEffect(()=>{
    void Promise.all([
      apiRequest<Space[]>('/office/spaces').then(rows=>setSpace(rows.find(x=>x.room===room)??null)),
      apiRequest<Presence[]>('/office/presence').then(rows=>setPeople(rows.filter(x=>x.room===room).map(x=>x.user.displayName))),
    ]).catch(()=>{setSpace(null);setPeople([])});
  },[room]);
  return <><p className="muted">{people.length?`${people.join(', ')} ${people.length===1?'is':'are'} here.`:'The room is currently empty.'}</p>{space?<button className="button blue wide" onClick={()=>{window.open(space.externalUrl,'_blank','noopener,noreferrer');close()}}>Open meeting link ↗</button>:<p className="form-message">No meeting link is configured for this room.</p>}</>;
}
function Modal({id,role,announcement,close,checkIn}:{id:Exclude<ModalId,null>;role:Role;announcement?:AnnouncementNote;close:()=>void;checkIn:(photo:File)=>Promise<void>}){const [photo,setPhoto]=useState<File|null>(null);const title=id==='leave'?'Request Leave':id==='task'?'New task':id==='announcement'?'New announcement':id==='announcement-detail'?(announcement?.[0]??'Announcement'):id==='people'?'Employees online':id==='photo-checkin'?'Office check-in':id==='review-reason'?'Add an explanation':id==='lounge'?'Lounge':id==='meeting-a'?'Meeting Room A':'Meeting Room B';return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="glass modal-card"><button className="icon-button modal-close" onClick={close}>×</button><p className="eyebrow">Komorebi Office</p><h2>{title}</h2>{id==='announcement-detail'&&announcement?<div className={`announcement-detail ${announcement[2]}`}><span className="note-pin">⌖</span><p>{announcement[1]}</p><div className="posted-by"><span className="avatar">{announcement[3][0]}</span><span><strong>{announcement[3]}</strong><small>{new Date(announcement[4]).toLocaleString()}</small></span></div></div>:id==='people'?<PeoplePanel/>:id==='photo-checkin'?<><p className="muted">Office check-in requires a photo taken at the workplace. WFH check-in never asks for one.</p><label className="photo-drop"><input type="file" accept="image/*" capture="environment" onChange={e=>setPhoto(e.target.files?.[0]??null)}/><strong>{photo?photo.name:'Choose or take an Office photo'}</strong><small>{photo?'Ready to check in':'JPG, PNG, or WebP'}</small></label><button className="button primary wide" disabled={!photo} onClick={()=>photo&&void checkIn(photo)}>Check in at Office</button></>:id==='meeting-a'||id==='meeting-b'?<MeetingPanel room={id==='meeting-a'?'MEETING_A':'MEETING_B'} close={close}/>:id==='lounge'?<p>The lounge is available for everyone in the Virtual Office.</p>:id==='review-reason'?<div className="modal-section"><label className="field">Explanation<textarea autoFocus placeholder="Tell the employee what needs to change or why this was rejected"/></label><div className="actions end"><button className="button secondary" onClick={close}>Cancel</button><button className="button primary" onClick={close}>Send response</button></div></div>:<Form id={id} role={role} close={close}/>}</section></div>}
function Form({id,role,close}:{id:ModalId;role:Role;close:()=>void}){const [assignees,setAssignees]=useState<string[]>([]);const [peopleOptions,setPeopleOptions]=useState<{id:string;displayName:string}[]>([]);const [teamOptions,setTeamOptions]=useState<{id:string;name:string}[]>([]);const [start,setStart]=useState('');const [end,setEnd]=useState('');const [error,setError]=useState('');const [saving,setSaving]=useState(false);const days=start&&end?Math.max(1,Math.round((new Date(end).getTime()-new Date(start).getTime())/86400000)+1):0;useEffect(()=>{if(id==='task')apiRequest<Array<{id:string;displayName:string}>>(role==='hr'?'/employees':'/team').then(setPeopleOptions).catch(()=>setPeopleOptions([]));if(id==='announcement'&&role==='hr')apiRequest<Array<{id:string;name:string}>>('/teams').then(setTeamOptions).catch(()=>setTeamOptions([]))},[id,role]);const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setSaving(true);setError('');const data=new FormData(e.currentTarget);try{if(id==='leave')await apiRequest('/leaves',{method:'POST',body:JSON.stringify({type:data.get('leaveType'),startDate:start,endDate:end,days,reason:data.get('description')})});if(id==='task')await apiRequest('/tasks',{method:'POST',body:JSON.stringify({title:data.get('title'),description:data.get('description'),priority:data.get('priority'),dueAt:data.get('dueAt')||undefined,assigneeIds:assignees})});if(id==='announcement'){const audience=String(data.get('audience')??'TEAM');const [audienceType,target]=audience.split(':');await apiRequest('/announcements',{method:'POST',body:JSON.stringify({title:data.get('title'),body:data.get('description'),audienceType,audienceTeamId:audienceType==='TEAM'?(target||undefined):undefined,audienceRole:audienceType==='ROLE'?target:undefined})});window.dispatchEvent(new Event('komorebi:announcements'))}close()}catch(ex){setError(ex instanceof Error?ex.message:'Unable to save')}finally{setSaving(false)}};return <form className="modal-section" onSubmit={submit}>{id==='leave'&&<><label className="field">Leave type<select name="leaveType"><option value="VACATION">Vacation</option><option value="SICK">Sick</option><option value="PERSONAL">Personal</option></select></label><div className="form-grid"><label className="field">Start Date<input type="date" required value={start} onChange={e=>setStart(e.target.value)}/></label><label className="field">End Date<input type="date" required value={end} min={start} onChange={e=>setEnd(e.target.value)}/></label></div><div className="duration">Duration <strong>{days} days</strong></div></>}<label className="field">{id==='task'?'Task name':'Title'}<input name="title" required={id!=='leave'} placeholder="Add a clear title"/></label><label className="field">{id==='leave'?'Reason':'Description'}<textarea name="description" required placeholder="Write the details"/></label>{id==='task'&&<><div className="form-grid"><label className="field">Priority<select name="priority"><option value="MEDIUM">Medium</option><option value="HIGH">High</option><option value="LOW">Low</option></select></label><label className="field">Due date<input name="dueAt" type="date"/></label></div><div className="field"><span>Assign to</span><div className="assignee-chips">{assignees.map(personId=><span key={personId}>{peopleOptions.find(x=>x.id===personId)?.displayName??personId}<button type="button" aria-label="Remove teammate" onClick={()=>setAssignees(assignees.filter(a=>a!==personId))}>×</button></span>)}</div><div className="assignee-row"><select defaultValue="" onChange={e=>{if(e.target.value&&!assignees.includes(e.target.value))setAssignees([...assignees,e.target.value]);e.target.value=''}}><option value="" disabled>Add a teammate…</option>{peopleOptions.filter(x=>!assignees.includes(x.id)).map(x=><option value={x.id} key={x.id}>{x.displayName}</option>)}</select></div></div></>}{id==='announcement'&&(role==='leader'?<><input type="hidden" name="audience" value="TEAM"/><div className="audience-lock">Audience: Your team</div></>:<label className="field">Audience<select name="audience"><option value="EVERYONE">Everyone</option>{teamOptions.map(x=><option key={x.id} value={`TEAM:${x.id}`}>Team · {x.name}</option>)}<option value="ROLE:EMPLOYEE">Role · Employees</option><option value="ROLE:TEAM_LEADER">Role · Team Leaders</option><option value="ROLE:HR">Role · HR</option></select></label>)}{error&&<p className="form-message">{error}</p>}<div className="actions end"><button type="button" className="button secondary" onClick={close}>Cancel</button><button className="button primary" disabled={saving||(id==='task'&&!assignees.length)||(id==='leave'&&!days)}>{saving?'Saving…':'Save'}</button></div></form>}
